package bys7.flutterassetsgen.core

/** Header shared by every generated `assets.dart`, regardless of [GenerationStyle]. */
internal const val GENERATED_HEADER = """// GENERATED CODE - DO NOT MODIFY BY HAND
// Generated by Flutter Assets Generator - press Alt+G to regenerate.

// ignore_for_file: type=lint"""

/** Only emitted when [LeafType.CLASS] is selected, since [ASSET_GEN_IMAGE_CLASS] needs Flutter's widget types. */
internal const val FLUTTER_WIDGETS_IMPORT = "import 'package:flutter/widgets.dart';"

/**
 * Typed wrapper emitted once per file when [LeafType.CLASS] is selected and used for
 * image-like assets (see [resolveFieldType]). Non-image assets (json, video, fonts, ...) stay
 * plain [String] regardless of [LeafType], since wrapping them in an image-flavored type would
 * be misleading.
 */
internal const val ASSET_GEN_IMAGE_CLASS = """class AssetGenImage {
  const AssetGenImage(this._assetName);

  final String _assetName;

  Image image({
    Key? key,
    AssetBundle? bundle,
    ImageFrameBuilder? frameBuilder,
    ImageErrorWidgetBuilder? errorBuilder,
    String? semanticLabel,
    bool excludeFromSemantics = false,
    double? scale,
    double? width,
    double? height,
    Color? color,
    Animation<double>? opacity,
    BlendMode? colorBlendMode,
    BoxFit? fit,
    AlignmentGeometry alignment = Alignment.center,
    ImageRepeat repeat = ImageRepeat.noRepeat,
    Rect? centerSlice,
    bool matchTextDirection = false,
    bool gaplessPlayback = false,
    bool isAntiAlias = false,
    String? package,
    FilterQuality filterQuality = FilterQuality.low,
    int? cacheWidth,
    int? cacheHeight,
  }) {
    return Image.asset(
      _assetName,
      key: key,
      bundle: bundle,
      frameBuilder: frameBuilder,
      errorBuilder: errorBuilder,
      semanticLabel: semanticLabel,
      excludeFromSemantics: excludeFromSemantics,
      scale: scale,
      width: width,
      height: height,
      color: color,
      opacity: opacity,
      colorBlendMode: colorBlendMode,
      fit: fit,
      alignment: alignment,
      repeat: repeat,
      centerSlice: centerSlice,
      matchTextDirection: matchTextDirection,
      gaplessPlayback: gaplessPlayback,
      isAntiAlias: isAntiAlias,
      package: package,
      filterQuality: filterQuality,
      cacheWidth: cacheWidth,
      cacheHeight: cacheHeight,
    );
  }

  ImageProvider provider({AssetBundle? bundle, String? package}) {
    return AssetImage(_assetName, bundle: bundle, package: package);
  }

  String get path => _assetName;

  String get keyName => _assetName;

  @override
  String toString() => _assetName;
}"""

/** Which Dart type a single asset's generated field gets. */
internal enum class FieldType { STRING, ASSET_IMAGE }

/** Raster-image extensions [Image.asset] can render directly. Everything else stays a plain String. */
private val IMAGE_EXTENSIONS = setOf("png", "jpg", "jpeg", "gif", "webp", "bmp")

/**
 * Resolves the per-file [FieldType]: always [FieldType.STRING] when the user picked the String
 * leaf type; when they picked Class, only genuine raster images become [FieldType.ASSET_IMAGE] -
 * other file kinds (json, mp4, mp3, fonts, svg, ...) stay [FieldType.STRING] since wrapping a
 * video or a font file in an "image" type would be actively misleading.
 */
internal fun resolveFieldType(fileName: String, leafType: LeafType): FieldType {
    if (leafType == LeafType.STRING) return FieldType.STRING
    val extension = fileName.substringAfterLast('.', "").lowercase()
    return if (extension in IMAGE_EXTENSIONS) FieldType.ASSET_IMAGE else FieldType.STRING
}

internal fun escapeDartString(value: String): String =
    value.replace("\\", "\\\\").replace("'", "\\'").replace("$", "\\$")

/**
 * Renders one asset member declaration for [fieldType].
 *
 * By default (`asGetter = false`) that's a `static const` field, used for the root class and for
 * the Legacy Flat style.
 *
 * With `asGetter = true` (members of the nested Hierarchical group classes) it's a getter:
 * `String get logo => '...';` / `AssetGenImage get logo => const AssetGenImage('...');`.
 * Deliberately not a `final` field: the group classes are const-constructed, and Dart's hot reload
 * can't add a field to a class that already has const instances (a full hot restart is needed).
 * A getter is just a method, so adding or removing assets works with a normal hot reload.
 */
internal fun fieldDeclaration(
    identifier: String,
    assetPath: String,
    fieldType: FieldType,
    asGetter: Boolean = false
): String {
    val value = escapeDartString(assetPath)
    return when (fieldType) {
        FieldType.STRING ->
            if (asGetter) "String get $identifier => '$value';" else "static const String $identifier = '$value';"

        FieldType.ASSET_IMAGE ->
            if (asGetter) {
                "AssetGenImage get $identifier => const AssetGenImage('$value');"
            } else {
                "static const AssetGenImage $identifier = AssetGenImage('$value');"
            }
    }
}
